const axios = require('axios');
const https = require('https');
const crypto = require('crypto');

// Authorization Key из личного кабинета GigaChat (строка в base64)
const GIGACHAT_AUTH_KEY = process.env.GIGACHAT_API_KEY;
// Для физлиц: GIGACHAT_API_PERS. Для бизнеса: GIGACHAT_API_B2B или GIGACHAT_API_CORP
const GIGACHAT_SCOPE = process.env.GIGACHAT_SCOPE || 'GIGACHAT_API_PERS';

const OAUTH_URL = 'https://ngw.devices.sberbank.ru:9443/api/v2/oauth';
const GIGACHAT_API_URL = 'https://gigachat.devices.sberbank.ru/api/v1/chat/completions';

// Сертификат Минцифры не знает Node.js, поэтому отключаем проверку
// только для запросов к GigaChat
const httpsAgent = new https.Agent({ rejectUnauthorized: false });

// --- Защита от спама: не более 30 сообщений в час с одного IP ---
// Счётчики живут в памяти экземпляра функции и обнуляются при холодном
// старте — это защита от массового спама, а не точный учёт.
const RATE_LIMIT_MAX = 30;
const RATE_LIMIT_WINDOW_MS = 60 * 60 * 1000; // 1 час
const rateBuckets = new Map();

function getClientIp(req) {
  const fwd = req.headers['x-forwarded-for'] || '';
  if (fwd) return String(fwd).split(',')[0].trim();
  return (req.socket && req.socket.remoteAddress) || 'unknown';
}

function checkRateLimit(ip) {
  const now = Date.now();
  let bucket = rateBuckets.get(ip);
  if (!bucket || now - bucket.start > RATE_LIMIT_WINDOW_MS) {
    bucket = { start: now, count: 0 };
    rateBuckets.set(ip, bucket);
  }
  bucket.count += 1;
  // Чистим устаревшие записи, чтобы память не разрасталась
  if (rateBuckets.size > 5000) {
    for (const [key, value] of rateBuckets) {
      if (now - value.start > RATE_LIMIT_WINDOW_MS) rateBuckets.delete(key);
    }
  }
  return bucket.count <= RATE_LIMIT_MAX;
}

// Сколько сообщений истории принимаем от клиента (защита от раздувания расхода)
const HISTORY_MAX_MESSAGES = 10;
const MESSAGE_MAX_CHARS = 2000;

const SYSTEM_PROMPT = 'Ты — Иван, продавец-консультант питомника «ЛесниковВ». Ты общаешься с покупателями в чате на сайте lesnikovv.ru. Твоя цель — помочь клиенту выбрать и купить растения из ассортимента питомника и довести его до заявки. Предлагай весь ассортимент: не только хвойные (сосна, ель, лиственница, туя, можжевельник), но и лиственные деревья (дуб, каштан, клён, ива) и кустарники (сирень, барбарис, спирея, чубушник, дерен). О компании: основан в 2005 году, руководитель Котынов Вячеслав Евгеньевич. Адрес: Нижегородская область, Кулебакский район, с. Теплово, ул. Новая, дом 12. Телефон: +7 902 783-59-36. Каталог (цены за 1 штуку, ориентировочные; наличие и итоговую цену всегда подтверждает менеджер). СЕЯНЦЫ: сосна обыкновенная, открытая корневая, 2-летние — 4 ₽; сосна ЗКС, 1–2-летние — 15 ₽; ель европейская ЗКС — 17 ₽; лиственница сибирская ЗКС — 17 ₽. САЖЕНЦЫ ХВОЙНЫЕ: сосна 3-летняя (от 40 см) — 60 ₽; сосна 3–4-летняя в контейнере (50–80 см) — 200 ₽; сосна с комом (1–2,5 м) — от 800 до 2300 ₽ по размеру; ель европейская 3-летняя — 70 ₽; ель 3–4-летняя в контейнере — 220 ₽; ель с комом (1–2,5 м) — от 1000 до 2500 ₽; ель колючая голубая 4-летняя — 600 ₽; туя «Брабант» — от 1000 ₽; туя «Даника» — 300–500 ₽; можжевельники (Олд Голд, казацкий, Грей Оул, Блю Эрроу) — 300–700 ₽. ЛИСТВЕННЫЕ: дуб красный — 150 ₽; каштан открытый — 150 ₽, в контейнере — 300 ₽; клён татарский — 200–400 ₽; ива шаровидная — 150–450 ₽; кустарники (дерен «Шпети», спирея «Грефшейм», чубушник, барбарис, сирень) — 250–400 ₽. Доставка: небольшие партии отправляем через Ozon по всей России (стоимость и сроки зависят от региона и размера заказа, точную сумму называет менеджер); крупные партии — автотранспортом (газель, Валдай, КамАЗ, фура); возможен самовывоз из питомника в с. Теплово. Сроки посадки: растения с открытой корневой системой сажают весной (апрель–май) и осенью (сентябрь–октябрь), пока нет жары и морозов; растения с закрытой корневой системой (ЗКС) можно сажать практически весь сезон — с апреля по октябрь, они лучше приживаются. Опт: для оптовиков и крупных заказчиков действуют специальные цены — чем больше объём, тем ниже цена за штуку; точные оптовые условия рассчитывает менеджер по телефону +7 902 783-59-36, всегда предлагай оптовикам позвонить. Подбор по почве и участку: сосна любит лёгкие песчаные и супесчаные почвы и солнце, не терпит застоя воды; ель предпочитает влажные плодородные, слегка кислые почвы, терпит тень; лиственница нетребовательна, растёт на бедных и переувлажнённых почвах, любит солнце; туя любит влажные дренированные почвы, выносит полутень; можжевельники светолюбивы и подходят для бедных песчаных почв; дуб и каштан — глубокие дренированные почвы без застоя воды; клён нетребователен и засухоустойчив; ива влаголюбива — для сырых мест и берегов; сирень не любит кислые почвы; дерен, спирея, барбарис и чубушник нетребовательны. Советы по посадке и уходу (давай их, когда спрашивают): яма в 1,5–2 раза шире кома, на тяжёлых почвах — дренаж; корневую шейку не заглублять; после посадки обильно полить (1–2 ведра на растение) и первый сезон поливать раз в неделю в сухую погоду; приствольный круг замульчировать торфом или щепой слоем 5–8 см, не вплотную к стволу, держать без сорняков; подкармливать не раньше следующего сезона; молодые саженцы на первую зиму можно укрыть лапником или спанбондом. Правила: 1) Здоровайся словом «Здравствуйте» ТОЛЬКО в самом первом своём ответе за весь диалог. Если диалог уже идёт или клиент здоровается повторно — НЕ здоровайся в ответ, просто продолжи разговор (например: «Слушаю вас», «Я здесь, что подсказать?»). 2) Всегда отвечай по существу заданного вопроса: если спрашивают про цену — назови цену, про доставку — расскажи про доставку. 3) Про погоду: если в сообщении клиента есть строка, начинающаяся с «ПОГОДА СЕЙЧАС В ПИТОМНИКЕ:», это настоящие свежие данные метеосервиса рядом с питомником — назови температуру и условия человеческим языком и добавь, подходит ли такая погода для посадки растений. Если такой строки нет, а про погоду спросили — скажи, что не можешь узнать погоду. 4) На остальные вопросы не по теме (новости, политика и т.п.) — честно скажи, что такой информацией не располагаешь, и мягко верни разговор к растениям. 5) Отвечай коротко, дружелюбно, по-человечески, в конце задай один уточняющий вопрос о потребностях клиента. 6) Расчёт заказа: если клиент называет товары и количество, посчитай ориентировочную сумму по ценам из каталога: сначала перечисли каждую позицию в виде «название — цена × количество = сумма», потом напиши «Итого ≈ ... ₽». Считай внимательно, перепроверь умножение. Если часть позиций с диапазоном, итог считай так: сначала сложи суммы всех позиций по минимальным ценам — это нижняя граница, потом по максимальным — это верхняя. Пример: позиции 3000 ₽ и 3000–5000 ₽ → итого от 6000 ₽ до 8000 ₽. Всегда добавляй, что это без учёта доставки и итоговую цену подтверждает менеджер, и предлагай оформить заявку на сайте или по телефону. Если в сообщении есть блок «КОРЗИНА КЛИЕНТА» — опирайся на него: можешь назвать сумму корзины и ответить на вопросы о ней.';

// Кэш токена, чтобы не запрашивать его при каждом сообщении
let cachedToken = null;
let tokenExpiresAt = 0;

async function getAccessToken() {
  // Берём токен из кэша, если он ещё действует (с запасом в минуту)
  if (cachedToken && Date.now() < tokenExpiresAt - 60 * 1000) {
    return cachedToken;
  }

  const response = await axios.post(
    OAUTH_URL,
    'scope=' + GIGACHAT_SCOPE,
    {
      headers: {
        'Authorization': 'Basic ' + GIGACHAT_AUTH_KEY,
        'RqUID': crypto.randomUUID(),
        'Content-Type': 'application/x-www-form-urlencoded',
        'Accept': 'application/json'
      },
      httpsAgent
    }
  );

  cachedToken = response.data.access_token;
  // expires_at приходит в миллисекундах
  tokenExpiresAt = response.data.expires_at || (Date.now() + 25 * 60 * 1000);
  return cachedToken;
}

module.exports = async (req, res) => {
  if (req.method !== 'POST') {
    return res.status(405).send('Method Not Allowed');
  }

  // Проверяем лимит ДО любых платных операций
  if (!checkRateLimit(getClientIp(req))) {
    return res.status(429).json({
      message: 'Вы отправили очень много сообщений за последний час. Пожалуйста, загляните чуть позже или позвоните нам: +7 902 783-59-36 — ответим на все вопросы!'
    });
  }

  try {
    const { message, history = [] } = req.body;

    // Берём только последние сообщения истории и режем слишком длинные,
    // чтобы клиент не мог раздуть расход токенов
    const safeHistory = (Array.isArray(history) ? history : [])
      .slice(-HISTORY_MAX_MESSAGES)
      .map(m => ({
        role: m && m.role === 'assistant' ? 'assistant' : 'user',
        content: String((m && m.content) || '').slice(0, MESSAGE_MAX_CHARS)
      }));

    const messages = [
      { role: 'system', content: SYSTEM_PROMPT },
      ...safeHistory,
      { role: 'user', content: String(message || '').slice(0, MESSAGE_MAX_CHARS) }
    ];

    const token = await getAccessToken();

    const response = await axios.post(
      GIGACHAT_API_URL,
      {
        model: 'GigaChat',
        messages: messages,
        temperature: 0.7,
      },
      {
        headers: {
          'Authorization': 'Bearer ' + token,
          'Content-Type': 'application/json',
          'Accept': 'application/json'
        },
        httpsAgent
      }
    );

    const aiReply = response.data.choices[0].message.content;

    return res.status(200).json({ message: aiReply });

  } catch (error) {
    // Если токен устарел или недействителен, сбрасываем кэш
    if (error.response && error.response.status === 401) {
      cachedToken = null;
    }
    const details = error.response
      ? error.response.status + ' ' + JSON.stringify(error.response.data)
      : error.message;
    console.error('Error:', details);
    return res.status(500).json({
      message: 'Ой, что-то связь с питомником прервалась. Попробуйте позже или напишите в WhatsApp: +7 902 783-59-36'
    });
  }
};
